/**
 * A Pokémon fainted before the turn with no replacement left: in 2v2 the UI passes its slot as null (doubles-types.ts
 * DoublesTurnInput.pokemon). Pinned Showdown c23d2e94 keeps it in its slot with fainted set, and allies(), foes(),
 * adjacency and every event skip it: it takes no action, a move aimed at it goes to the other foe, a spread move counts only
 * the Pokémon in place (one target: no spread modifier), its partner gets none of its effects, and side.totalFainted counts
 * it (Last Respects). The cases' values are the exact oracle of scripts/.cache/calc-audit/2v2/verify/sim-dfs.ts, the slot's
 * Pokémon entering at the start and fainting before the turn (fainted-engine/real-battle.ts gives the same turns from a real
 * battle where it was knocked out the turn before). Level 50, 31 IVs, Serious nature and 0 EVs / Stat Points unless set.
 * Generated by scripts/.cache/calc-audit/2v2/fainted-engine/gen-fainted-tests.ts.
 */
type Stat = "hp" | "atk" | "def" | "spa" | "spd" | "spe";
type Mon = {
  species: string; appSpecies?: string; ability: string; item?: string; nature?: string; evs?: Partial<Record<Stat, number>>;
  ivs?: Partial<Record<Stat, number>>; level?: number; hp?: number; status?: BattleBuild["status"];
  boosts?: Partial<Record<Exclude<Stat, "hp">, number>>; absent?: boolean; move: string | null; target?: DoublesSlotId; context?: MoveContext;
};
type Field = Partial<Pick<BattleConditions, "weather" | "terrain">>;
type HP = { start: number; maximum: number; low: number; high: number; min: number; max: number; average: number; koChance: number; faintsBeforeMoving?: number };
type Hit = { slot: DoublesSlotId; reached: number; koChance: number; min?: number; max?: number; kind?: "blocked" };
type Step = { moveId: string; moves: number; order: [number, number][]; hits: Hit[] };
type Case = {
  id: string; game: "sv" | "swsh" | "usum" | "champions"; title: string; checks: string; field?: Field;
  slots: Record<DoublesSlotId, Mon>; hp: Record<DoublesSlotId, HP | null>; steps: Partial<Record<DoublesSlotId, Step>>;
};

const GAMES: Record<Case["game"], BattleGame> = { sv: "scarlet_violet", swsh: "sword_shield", usum: "ultra_sun_ultra_moon", champions: "champions" };
const SLOTS: DoublesSlotId[] = ["own-left", "own-right", "opponent-left", "opponent-right"];
const id = (text: string) => text.toLowerCase().replace(/[^a-z0-9]+/g, "");
const ZERO = { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 };

/** The app build for an oracle set: Showdown names as ids, EVs (native) or Stat Points (Champions), the start state. */
function caseBuild(m: Mon, runtime: BattleRuntime): BattleBuild {
  const base = createBuild(m.appSpecies ?? id(m.species), runtime);
  const abilityId = id(m.ability);
  const shared = {
    nature: m.nature ?? "Serious", abilityId, abilityActive: defaultAbilityActive(abilityId), itemId: id(m.item ?? ""),
    boosts: { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, ...m.boosts }, currentHP: m.hp ?? null, status: m.status ?? "",
  };
  return (base.game === "champions"
    ? { ...base, ...shared, points: { ...ZERO, ...m.evs } }
    : { ...base, ...shared, native: { level: m.level ?? 50, evs: { ...ZERO, ...m.evs }, ivs: { hp: 31, atk: 31, def: 31, spa: 31, spd: 31, spe: 31, ...m.ivs } } }) as BattleBuild;
}
async function caseInput(c: Case): Promise<DoublesTurnInput> {
  const runtime = await loadBattleRuntime(GAMES[c.game]);
  const field: BattleConditions = { ...createConditions(), gameType: "Doubles", weather: c.field?.weather ?? "", terrain: c.field?.terrain ?? "", attackerSide: createSide(), defenderSide: createSide() };
  const pokemon = Object.fromEntries(SLOTS.map((slot) => {
    const m = c.slots[slot];
    // The fainted Pokémon's slot is empty in the input.
    if (m.absent) return [slot, null];
    const moveId = m.move === null ? null : id(m.move);
    const entry: DoublesPokemonInput = {
      build: caseBuild(m, runtime), contexts: moveId && m.context ? { [moveId]: m.context } : {}, charged: false, action: { moveId, target: m.target ?? null },
    };
    return [slot, entry];
  })) as Record<DoublesSlotId, DoublesPokemonInput | null>;
  return { runtime, field, pokemon };
}

