describe("a Pokémon fainted before the turn, against pinned Showdown", () => {
  for (const c of CASES) {
    it(`${c.id}: ${c.title}`, async () => {
      const result = calculateDoublesTurn(await caseInput(c));
      expect(result.status, c.checks).toBe("ready");
      if (result.status !== "ready") return;
      for (const slot of SLOTS) {
        const want = c.hp[slot], got = result.hp[slot];
        if (!want) { expect(got, slot).toBeNull(); continue; }
        expect(got, slot).not.toBeNull();
        expect({ start: got!.start, maximum: got!.maximum, low: got!.low, high: got!.high, min: got!.min, max: got!.max }, `${c.id} ${slot}`)
          .toEqual({ start: want.start, maximum: want.maximum, low: want.low, high: want.high, min: want.min, max: want.max });
        expect(got!.average, `${c.id} ${slot} average`).toBeCloseTo(want.average, 9);
        expect(Math.abs(got!.koChance - want.koChance), `${c.id} ${slot} KO chance`).toBeLessThanOrEqual(1e-9);
        expect(got!.faintsBeforeMoving ?? 0, `${c.id} ${slot} faints before moving`).toBeCloseTo(want.faintsBeforeMoving ?? 0, 9);
      }
      // No step for the fainted Pokémon: only the slots with a move that are in place.
      expect(result.steps.map((step) => step.slot).sort()).toEqual(Object.keys(c.steps).sort());
      for (const step of result.steps) {
        const want = c.steps[step.slot]!;
        expect(step.moveId).toBe(want.moveId);
        expect(step.moves, `${c.id} ${step.slot} moves`).toBeCloseTo(want.moves, 9);
        expect(step.order.map((entry) => [entry.position, entry.chance])).toEqual(want.order);
        if (!want.hits.length) { expect(step.hits.filter((hit) => hit.reached > 0), `${c.id} ${step.slot} hits`).toEqual([]); continue; }
        expect(step.hits.map((hit) => hit.slot).sort(), `${c.id} ${step.slot} hits`).toEqual(want.hits.map((hit) => hit.slot).sort());
        for (const hit of want.hits) {
          const got = step.hits.find((h) => h.slot === hit.slot)!;
          expect(got.reached, `${c.id} ${step.slot} → ${hit.slot} reached`).toBeCloseTo(hit.reached, 9);
          expect(got.koChance, `${c.id} ${step.slot} → ${hit.slot} KO chance`).toBeCloseTo(hit.koChance, 9);
          if (hit.min !== undefined) expect({ kind: got.kind, min: got.min, max: got.max }, `${c.id} ${step.slot} → ${hit.slot}`).toEqual({ kind: "calculated", min: hit.min, max: hit.max });
          else expect(got.kind === "blocked" || got.kind === "no-damage").toBe(true);
        }
      }
    });
  }
});

// ---------------------------------------------------------------------------------------------------------------------------
// The engine's rules for empty slots (doubles-targets.ts doublesTargetRule, doubles-turn.ts), and the 1v1 parity.
// ---------------------------------------------------------------------------------------------------------------------------

type P = {
  id: string; ability?: string; item?: string; nature?: string; evs?: Partial<StatTable>; hp?: number; move?: string | null; target?: DoublesSlotId;
  contexts?: Record<string, MoveContext>;
};
function turn(runtime: BattleRuntime, slots: Record<DoublesSlotId, P | null>, field: Partial<BattleConditions> = {}): DoublesTurnInput {
  const pokemon = Object.fromEntries(SLOTS.map((slot) => {
    const p = slots[slot];
    if (!p) return [slot, null];
    const base = createBuild(p.id, runtime);
    const abilityId = p.ability ?? base.abilityId;
    const trained = base.game === "champions" ? { points: { ...ZERO, ...p.evs } } : { native: { ...base.native!, evs: { ...ZERO, ...p.evs } } };
    const build = {
      ...base, ...trained, nature: p.nature ?? "Serious", abilityId, abilityActive: defaultAbilityActive(abilityId), itemId: p.item ?? base.itemId, currentHP: p.hp ?? null,
    } as BattleBuild;
    const entry: DoublesPokemonInput = { build, contexts: p.contexts ?? {}, charged: false, action: { moveId: p.move ?? null, target: p.target ?? null } };
    return [slot, entry];
  })) as Record<DoublesSlotId, DoublesPokemonInput | null>;
  return { runtime, field: { ...createConditions(), gameType: "Doubles", ...field }, pokemon };
}
const idle = (id: string, extra: Partial<P> = {}): P => ({ id, move: null, ...extra });
function ready(result: DoublesTurnResult) {
  expect(result.status, result.status === "not-estimated" ? result.reason : result.status === "issues" ? JSON.stringify(result.issues) : "").toBe("ready");
  if (result.status !== "ready") throw new Error("not ready");
  return result;
}
const NO_FOE = "No target: both foes have fainted.";

describe("target rules with an empty slot", () => {
  it("leave the empty slot out of every option and hit list", () => {
    const lone = turn(championsRuntime, { "own-left": idle("garchomp"), "own-right": null, "opponent-left": null, "opponent-right": idle("blastoise") });
    expect(doublesTargetRule(lone, "own-left", "dragonclaw")).toEqual({ kind: "choose", options: ["opponent-right"] });
    expect(doublesTargetRule(lone, "own-left", "rockslide")).toEqual({ kind: "auto", hits: ["opponent-right"] });
    expect(doublesTargetRule(lone, "own-left", "earthquake")).toEqual({ kind: "auto", hits: ["opponent-right"] });
    expect(doublesTargetRule(lone, "opponent-right", "surf")).toEqual({ kind: "auto", hits: ["own-left"] });
    const alone = turn(championsRuntime, { "own-left": idle("clefable"), "own-right": null, "opponent-left": idle("garchomp"), "opponent-right": idle("blastoise") });
    expect(doublesTargetRule(alone, "own-left", "helpinghand")).toEqual({ kind: "auto", hits: [] });
  });

  it("give a move that can reach a foe no target once both foe slots are empty", () => {
    const won = turn(championsRuntime, { "own-left": idle("garchomp"), "own-right": idle("clefable"), "opponent-left": null, "opponent-right": null });
    // Not even the ally: a single-target move into a foe has nothing to aim at.
    expect(doublesTargetRule(won, "own-left", "dragonclaw")).toEqual({ kind: "choose", options: [] });
    expect(doublesTargetRule(won, "own-left", "rockslide")).toEqual({ kind: "auto", hits: [] });
    expect(doublesTargetRule(won, "own-left", "earthquake")).toEqual({ kind: "auto", hits: [] });
    expect(doublesTargetRule(won, "own-right", "helpinghand")).toEqual({ kind: "auto", hits: ["own-left"] });
    expect(doublesTargetRule(won, "own-left", "protect")).toEqual({ kind: "none", scope: "self" });
  });
});

/** Garchomp's Dragon Claw at `target`, the opponent-left slot empty. */
const at = (target: DoublesSlotId) => turn(championsRuntime, {
  "own-left": { id: "garchomp", ability: "sandveil", move: "dragonclaw", target }, "own-right": idle("venusaur"), "opponent-left": null, "opponent-right": idle("blastoise"),
});

describe("validation with an empty slot", () => {

  it("takes a move aimed at an empty foe slot to the other foe, as pinned Showdown retargets it (getTarget, getRandomTarget)", () => {
    expect(ready(calculateDoublesTurn(at("opponent-left")))).toEqual(ready(calculateDoublesTurn(at("opponent-right"))));
  });

  it("rejects a move aimed at an empty ally slot", () => {
    const result = calculateDoublesTurn(turn(championsRuntime, {
      "own-left": { id: "garchomp", move: "dragonclaw", target: "own-right" }, "own-right": null, "opponent-left": idle("venusaur"), "opponent-right": idle("blastoise"),
    }));
    expect(result.status).toBe("issues");
    if (result.status === "issues") expect(result.issues.actions).toEqual([{ slot: "own-left", message: "This move cannot target that Pokémon." }]);
  });
});

describe("both foes fainted", () => {
  it("is a ready turn with no steps when every move has no target", () => {
    const result = ready(calculateDoublesTurn(turn(championsRuntime, {
      "own-left": { id: "garchomp", move: "dragonclaw" }, "own-right": { id: "charizard", move: "heatwave" }, "opponent-left": null, "opponent-right": null,
    })));
    expect(result.steps).toEqual([]);
    expect(result.startRows).toEqual([]);
    expect(result.facts).toContain(NO_FOE);
    expect(result.hp["opponent-left"]).toBeNull();
    expect(result.hp["opponent-right"]).toBeNull();
    for (const slot of ["own-left", "own-right"] as const) {
      const hp = result.hp[slot]!;
      expect({ low: hp.low, high: hp.high, min: hp.min, max: hp.max, koChance: hp.koChance }).toEqual({ low: hp.start, high: hp.start, min: hp.start, max: hp.start, koChance: 0 });
      expect(hp.faintsBeforeMoving).toBeUndefined();
    }
  });

  it("still runs a move that needs no foe, numbered among the steps alone", () => {
    const result = ready(calculateDoublesTurn(turn(championsRuntime, {
      "own-left": { id: "garchomp", move: "dragonclaw" }, "own-right": { id: "clefable", ability: "magicguard", move: "lightscreen" }, "opponent-left": null, "opponent-right": null,
    })));
    expect(result.steps.map((step) => [step.slot, step.moveId, step.order])).toEqual([["own-right", "lightscreen", [{ position: 1, chance: 1 }]]]);
    expect(result.steps[0].facts.map((fact) => fact.text)).toEqual(["Light Screen starts on Clefable's side."]);
    expect(result.facts).toContain(NO_FOE);
  });

  it("is not stated while a foe is in place", () => {
    const result = ready(calculateDoublesTurn(at("opponent-right")));
    expect(result.facts).not.toContain(NO_FOE);
  });
});

describe("a move aimed at the ally with the ally slot empty", () => {
  it("fails before any later move: Helping Hand, Aromatic Mist (K07a, K07b)", async () => {
    const helping = ready(calculateDoublesTurn(turn(championsRuntime, {
      "own-left": { id: "clefable", ability: "magicguard", move: "helpinghand" }, "own-right": null,
      "opponent-left": { id: "garchomp", ability: "sandveil", move: "rockslide" }, "opponent-right": idle("blastoise"),
    })));
    expect(helping.steps.find((step) => step.slot === "own-left")).toMatchObject({ moves: 1, hits: [], facts: [{ text: "Helping Hand fails: its ally has fainted.", chance: 1 }] });
    const sv = await loadBattleRuntime("scarlet_violet");
    const mist = ready(calculateDoublesTurn(turn(sv, {
      "own-left": { id: "alcremie", ability: "sweetveil", move: "aromaticmist" }, "own-right": null,
      "opponent-left": idle("garchomp"), "opponent-right": { id: "snorlax", ability: "thickfat", move: "bodyslam", target: "own-left" },
    })));
    expect(mist.steps.map((step) => [step.slot, step.order[0].position, step.facts.map((fact) => fact.text)])).toEqual([
      ["own-left", 1, ["Aromatic Mist fails: its ally has fainted."]], ["opponent-right", 2, []],
    ]);
  });
});

describe("Last Respects", () => {
  it("counts the side's empty slot among its fainted, never twice (K11a, K11b)", async () => {
    const sv = await loadBattleRuntime("scarlet_violet");
    const line = (fainted: number | undefined) => {
      const input = turn(sv, {
        "own-left": { id: "basculegion", ability: "swiftswim", contexts: fainted === undefined ? {} : { lastrespects: { fainted } } }, "own-right": null,
        "opponent-left": idle("venusaur"), "opponent-right": idle("snorlax"),
      });
      const row = calculateDoublesMoves(input, "own-left", "opponent-left").results.find((each) => each.moveId === "lastrespects")!;
      return row.assumptions.find((text) => text.startsWith("Last Respects:"));
    };
    expect(line(undefined)).toBe("Last Respects: 1 fainted, 100 power.");
    expect(line(0)).toBe("Last Respects: 1 fainted, 100 power.");
    expect(line(1)).toBe("Last Respects: 1 fainted, 100 power.");
    expect(line(2)).toBe("Last Respects: 2 fainted, 150 power.");
  });
});

// The 1v1 calculator with gameType Doubles and Multiple targets hit off: one Pokémon per side in 2v2 is that matchup.
/** Moves whose 1v1 row depends on the turn order or an event of the turn (event-moves.ts, count-moves.ts, turn-order.ts). */
const TURN_DEPENDENT = new Set([
  "payback", "boltbeak", "fishiousrend", "analytic", "avalanche", "revenge", "assurance", "lashout", "round", "stompingtantrum", "temperflare",
  "lastrespects", "ragefist", "beatup", "suckerpunch", "thunderclap", "upperhand", "focuspunch", "fakeout", "firstimpression", "metalburst", "counter", "mirrorcoat", "comeuppance",
]);
const damage = (row: MoveDamageResult) => ({
  kind: row.kind, min: row.min, max: row.max, minPercent: row.minPercent, maxPercent: row.maxPercent, rolls: row.rolls, hits: row.hits, ohkoChance: row.ohkoChance,
  usesToKO: row.usesToKO, afterUse: row.afterUse && { start: row.afterUse.start, low: row.afterUse.low, high: row.afterUse.high, koChance: row.afterUse.koChance },
});
function expectSameRows(doubles: MoveDamageResult[], single: MoveDamageResult[]) {
  const byMove = new Map(single.map((row) => [row.moveId, row]));
  expect(doubles.map((row) => row.moveId).sort()).toEqual(single.map((row) => row.moveId).sort());
  let compared = 0;
  for (const row of doubles) {
    if (TURN_DEPENDENT.has(row.moveId)) continue;
    expect(damage(row), row.moveId).toEqual(damage(byMove.get(row.moveId)!));
    compared++;
  }
  expect(compared).toBeGreaterThan(20);
}
const oneTarget = (): BattleConditions => ({ ...createConditions(), gameType: "Doubles", multipleTargets: false });

describe("one Pokémon per side equals the 1v1 calculator in Doubles with Multiple targets hit off", () => {
  const pairs: [BattleGame, string, string][] = [
    ["champions", "garchomp", "blastoise"], ["scarlet_violet", "garchomp", "snorlax"], ["sword_shield", "charizard", "venusaur"], ["ultra_sun_ultra_moon", "garchomp", "blastoise"],
  ];
  for (const [game, attacker, defender] of pairs) {
    it(`${game}: every move of ${attacker} into ${defender} and back, single-target and spread`, async () => {
      const runtime = await loadBattleRuntime(game);
      const input = turn(runtime, { "own-left": idle(attacker), "own-right": null, "opponent-left": null, "opponent-right": idle(defender) });
      const own = input.pokemon["own-left"]!.build, foe = input.pokemon["opponent-right"]!.build;
      const rows = calculateDoublesMoves(input, "own-left", "opponent-right");
      expect(rows.issues).toEqual({ attacker: [], defender: [], field: [] });
      expectSameRows(rows.results, calculateMatchup(own, foe, oneTarget(), {}, runtime).results);
      expectSameRows(calculateDoublesMoves(input, "opponent-right", "own-left").results, calculateMatchup(foe, own, oneTarget(), {}, runtime).results);
    });
  }

  it("gives the turn's hit into the lone foe the 1v1 row: Dragon Claw, Rock Slide, Earthquake, Heat Wave", () => {
    const cases: [string, string][] = [["garchomp", "dragonclaw"], ["garchomp", "rockslide"], ["garchomp", "earthquake"], ["charizard", "heatwave"]];
    for (const [attacker, move] of cases) {
      const target = move === "dragonclaw" ? "opponent-right" : undefined;
      const input = turn(championsRuntime, { "own-left": { id: attacker, move, target }, "own-right": null, "opponent-left": null, "opponent-right": idle("snorlax") });
      const single = calculateMatchup(input.pokemon["own-left"]!.build, input.pokemon["opponent-right"]!.build, oneTarget(), {}, championsRuntime).results.find((row) => row.moveId === move)!;
      const result = ready(calculateDoublesTurn(input));
      expect(result.steps.map((step) => step.hits.map((hit) => hit.slot)), move).toEqual([["opponent-right"]]);
      const hit = result.steps[0].hits[0];
      expect({ kind: hit.kind, min: hit.min, max: hit.max, rolls: hit.row?.rolls }, move).toEqual({ kind: "calculated", min: single.min, max: single.max, rolls: single.rolls });
      expect(result.startRows.map((row) => [row.slot, row.target, damage(row.row)]), move).toEqual([["own-left", "opponent-right", damage(single)]]);
      // All lowest rolls leave the foe at its start less the lowest roll; all highest, less the highest.
      const hp = result.hp["opponent-right"]!;
      expect([hp.low, hp.high], move).toEqual([hp.start - single.min!, hp.start - single.max!]);
    }
  });

  it("gives Last Respects the 1v1 row with the empty slot as one fainted", async () => {
    const sv = await loadBattleRuntime("scarlet_violet");
    const input = turn(sv, { "own-left": idle("basculegion", { ability: "swiftswim" }), "own-right": null, "opponent-left": null, "opponent-right": idle("venusaur") });
    const row = calculateDoublesMoves(input, "own-left", "opponent-right").results.find((each) => each.moveId === "lastrespects")!;
    const single = calculateMatchup(input.pokemon["own-left"]!.build, input.pokemon["opponent-right"]!.build, oneTarget(), { lastrespects: { fainted: 1 } }, sv).results.find((each) => each.moveId === "lastrespects")!;
    expect(damage(row)).toEqual(damage(single));
  });
});
